  if (val &gt; 700) {
    digitalWrite(ALARM_LED, HIGH);
    Serial.println("  ==&gt; [ALERT]: OVERHEAT THRESHOLD EXCEEDED! (LED ON)");
  } else {
    digitalWrite(ALARM_LED, LOW);
  }
}

